module protocol::reserve;

use sui::balance::{Self, Balance, Supply};
use sui::coin::{Coin};
use sui::dynamic_field;

use protocol::ctoken::CToken;
use protocol::error;
use protocol::ctoken;
use math::float::{Self, Decimal};
use protocol::borrow_index::{Self, BorrowIndex};

public struct Reserve<phantom MarketType> has key, store {
    id: UID,

    debt: Decimal,
    cash_reserve: Decimal,

    // cash equals to ReserveBalance.underlying_balance, it is required as util_rate requires query without generic type
    cash: u64,
    // total_suppy equals to ReserveBalance.ctoken_supply.supply_value, it is required as exchange_rate requires query without generic type
    total_supply: u64,

    borrow_index: BorrowIndex,
}

public struct ReserveBalanceKey has copy, drop, store {} 
public struct ReserveBalance<phantom MarketType, phantom CoinType> has store {
    underlying_balance: Balance<CoinType>,
    ctoken_supply: Supply<CToken<MarketType, CoinType>>,
}

public struct ReserveFlashLoan<phantom MarketType, phantom CoinType> {
    amount: u64,
}

// create a vault for storing underlying assets and market coin supplies
public(package) fun new<MarketType, CoinType>(ctx: &mut TxContext, now: u64): Reserve<MarketType> {
    let mut reserve = Reserve {
        id: object::new(ctx),
        cash: 0,
        debt: float::zero(),
        cash_reserve: float::zero(),
        total_supply: 0,

        borrow_index: borrow_index::new(now),
    };

    dynamic_field::add(
        &mut reserve.id,
        ReserveBalanceKey {},
        ReserveBalance<MarketType, CoinType> {
            underlying_balance: balance::zero<CoinType>(),
            ctoken_supply: balance::create_supply(ctoken::new()),
        }
    );

    reserve
}

public(package) fun debt<MarketType>(self: &Reserve<MarketType>): &Decimal { &self.debt }

public(package) fun borrow_index<MarketType>(self: &Reserve<MarketType>): &BorrowIndex { &self.borrow_index }

public(package) fun util_rate<MarketType>(self: &Reserve<MarketType>): Decimal {
    if (self.debt.is_zero()) {
        return float::from_quotient(0, 1)
    };

    let denominator = self.cash_plus_borrows_minus_reserves();
    self.debt.div(denominator)
}

public(package) fun cash_plus_borrows_minus_reserves<MarketType,>(self: &Reserve<MarketType>): Decimal {
    self.debt.add_u64(self.cash).sub(self.cash_reserve)
}

public(package) fun protocol_reserve<MarketType>(self: &Reserve<MarketType>): u64 {
    self.cash_reserve.floor()
}

public(package) fun total_deposit_plus_interest<MarketType,>(self: &Reserve<MarketType>): Decimal {
    self.exchange_rate().mul_u64(self.total_supply)
}

/// Caller should ensure this asset can be collateral
public(package) fun deposit_limit_breached<MarketType>(self: &Reserve<MarketType>, increment: u64, limit: u64): bool {
    let total_deposit_plus_interest = self.total_deposit_plus_interest();
    total_deposit_plus_interest.ceil() + increment - self.cash_reserve.ceil() > limit
}

public(package) fun exchange_rate<MarketType>(self: &Reserve<MarketType>): Decimal {
    if (self.total_supply == 0) {
        return float::from_quotient(1, 1)
    };

    let numerator = self.cash_plus_borrows_minus_reserves();
    let denominator = float::from(self.total_supply);

    numerator.div(denominator)
}

// ===================== Update Functions ================

public(package) fun calculate_borrow_index<MarketType>(
    self: &Reserve<MarketType>,
    interest_rate: Decimal,
    now: u64,
): Decimal {
    let borrow_index_prior = self.borrow_index.value();

    // if the interest has been accrued, skip
    let last_updated = self.borrow_index.last_updated();
    if (last_updated == now) {
        return borrow_index_prior
    };

    let simple_interest_factor = interest_rate.mul_u64(now - last_updated);

    // mul_ScalarTruncateAddUInt(simpleInterestFactor, borrowIndexPrior, borrowIndexPrior);

/// @title Module for flash loan from base asset pools
module protocol::flash_loan;

use std::type_name::{Self, TypeName};
use std::string::String;

use sui::coin::Coin;
use sui::clock::Clock;

use sui::event::emit;

use x_oracle::x_oracle::XOracle;
use x_oracle::user_oracle::get_price;

use protocol::app::{ProtocolApp, PackageCallerCap};
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::{Market, FlashLoan};
use protocol::value::coin_value;

public struct BorrowFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public struct RepayFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public fun borrow_flash_loan<MarketType, CoinType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    market: &mut Market<MarketType>,

    emode_group: u8,
    amount: u64,

    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    app.ensure_has_permission(object::id(cap), protocol::whitelist_admin::flash_loan());

    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

/// @notice Repay flash loan to market
/// @dev This is the only method to repay flash loan, consume the flash loan hot potato object
/// @param version The version control object, contract version must match with this
/// @param market The market object, it contains base assets, and related protocol configs
/// @param coin The coin object to repay
/// @param loan The flash loan hot potato object, which contains the borrowed amount and fee
/// @ctx The SUI transaction context object
/// @custom:T The type of asset to repay
public fun repay_flash_loan<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, std::option::none(), ctx);
}

public fun repay_flash_loan_increase_referral_qualification<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    maybe_referral_code: Option<String>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    track_referral(referral, ctx.sender(), loan.loan_amount(), type_name::with_defining_ids<CoinType>(), coin_decimals_registry, x_oracle, clock);
    let maybe_referral_code = referral.try_map_referral_code(ctx.sender(), maybe_referral_code);

    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, maybe_referral_code, ctx);
}

fun borrow_flash_loan_inner<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let (coin, flash_loan) = market.borrow_flash_loan(emode_group, amount, ctx);

    // Emit the borrow flash loan event
    emit(BorrowFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        fee: flash_loan.fee(),
        amount,
    });

    // Return the borrowed coin object and the flash loan hot potato object
    (coin, flash_loan)
}

fun track_referral(
    referral: &mut protocol::referral::Referral,

    who: address,

    token_amount: u64,
    token_type: TypeName,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
) {
    if (referral.is_qualified_to_create_referral_code(who)) return;

    let decimals = coin_decimals_registry.decimals(token_type);
    // always use usd price
    let usd_price = get_price(x_oracle, token_type, x_oracle::x_oracle::usd(), clock);
    let collateral_value_usd = coin_value(usd_price, math::float::from(token_amount), decimals);

    referral.increase_usd_qualification(who, collateral_value_usd.floor());
}

#[test_only]
public fun borrow_flash_loan_against_group<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

